+
+function streamAll(chunks: string[]): string[][] {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const chunk of chunks) rows.push(...s.push(chunk));
+  rows.push(...s.end());
+  return rows;
+}
+
+function parseOrError(f: () => string[][]): string[][] | "SyntaxError" {
+  try {
+    return f();
+  } catch (e) {
+    if (e instanceof SyntaxError) return "SyntaxError";
+    throw e;
+  }
+}
+
+/** Every way of cutting `text` at up to two places, including empty chunks. */
+function splits(text: string): string[][] {
+  const out: string[][] = [];
+  for (let a = 0; a <= text.length; a++)
+    for (let b = a; b <= text.length; b++) out.push([text.slice(0, a), text.slice(a, b), text.slice(b)]);
+  return out;
+}
+
+const tricky = [
+  "",
+  "\n",
+  "\r\n",
+  "\r",
+  "a\r",
+  "a\rb\r\n",
+  '"a"\r\n',
+  '"a"\r',
+  '"a"\rb',
+  '"a""b"',
+  '"a"""',
+  '""',
+  '"',
+  '"a\r\n,b"\n',
+  "a,",
+  "a,\n",
+  ",",
+  "\n\n",
+  "﻿",
+  "﻿\n",
+  "﻿a,b",
+  "a﻿",
+  '"a"b',
+  'a"b',
+  '\r"',
+  "a,b\r\nc,d\n",
+];
+
+test("a stream matches parseCsv for every split of tricky inputs", () => {
+  for (const text of tricky) {
+    const expected = parseOrError(() => parseCsv(text));
+    for (const chunks of splits(text)) expect([text, chunks, parseOrError(() => streamAll(chunks))]).toEqual([text, chunks, expected]);
+  }
+});
+
+test("a stream matches parseCsv on random inputs split at random places", () => {
+  let seed = 12345;
+  const next = (n: number) => {
+    seed = (seed * 1103515245 + 12345) % 2147483648;
+    return seed % n;
+  };
+  const alphabet = ["a", "b", ",", '"', "\r", "\n", "﻿"];
+  for (let t = 0; t < 3000; t++) {
+    let text = "";
+    const len = next(16);
+    for (let k = 0; k < len; k++) text += alphabet[next(alphabet.length)];
+    const chunks: string[] = [];
+    let at = 0;
+    while (at < text.length) {
+      const size = next(4);
+      chunks.push(text.slice(at, at + size));
+      at += size;
+    }
+    expect([text, chunks, parseOrError(() => streamAll(chunks))]).toEqual([text, chunks, parseOrError(() => parseCsv(text))]);
+  }
+});
+
+test("a stream returns a row only once its whole row end has arrived", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\nb\n")).toEqual([["a"], ["b"]]);
+  expect(s.push('"c"')).toEqual([]);
+  expect(s.push('"')).toEqual([]);
+  expect(s.push('"\n')).toEqual([['c"']]);
+  expect(s.end()).toEqual([]);
+});
+
+test("a stream throws SyntaxError where parseCsv does, and keeps throwing", () => {
+  const s = new CsvStream();
+  expect(s.push('"a"')).toEqual([]);
+  expect(() => s.push("b")).toThrow(SyntaxError);
+  expect(() => s.push("\n")).toThrow(SyntaxError);
+  expect(() => s.end()).toThrow(SyntaxError);
+  const open = new CsvStream();
+  expect(open.push('"a\n')).toEqual([]);
+  expect(() => open.end()).toThrow("a quoted field is still open at the end of the input");
+  const cr = new CsvStream();
+  expect(cr.push('"a"\r')).toEqual([]);
+  expect(() => cr.push("x")).toThrow('unexpected "\\r" after a closing quote at offset 3');
+});
+
+test("a stream cannot be used after end", () => {
+  const s = new CsvStream();
+  s.end();
+  expect(() => s.push("a")).toThrow("the stream has already ended");
+  expect(() => s.end()).toThrow("the stream has already ended");
+});
+
+test("a long field split into many chunks", () => {
+  const s = new CsvStream();
+  expect(s.push('"')).toEqual([]);
+  for (let k = 0; k < 10000; k++) expect(s.push("x")).toEqual([]);
+  expect(s.push('"\n')).toEqual([["x".repeat(10000)]]);
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-28 09:31:38.906347533 +0000
+++ b/csv.ts	2026-10-28 09:32:21.991191606 +0000
@@ -50,3 +50,174 @@
   rows.push(row);
   return rows;
 }
+
+const enum State {
+  /** At the start of a row: nothing of it has arrived yet. */
+  RowStart,
+  /** Just after a `,`: the next field has not started yet. */
+  FieldStart,
+  /** Inside a field that is not quoted. */
+  Unquoted,
+  /** Inside a quoted field. */
+  Quoted,
+  /** A `"` inside a quoted field: either the first of `""` or the closing quote. */
+  QuoteInQuoted,
+  /** After the closing quote of a field. */
+  AfterQuote,
+  /** A `\r` outside quotes, waiting to see whether `\n` follows. */
+  CarriageReturn,
+}
+
+/**
+ * Parses CSV that arrives in chunks, by the rules of `parseCsv`: for any input and any way of splitting it into
+ * chunks, the rows from all the `push` calls and the `end` call together equal `parseCsv` of the whole input, and
+ * an input `parseCsv` rejects makes a `push` or `end` throw a SyntaxError. The work for a chunk depends only on the
+ * chunk and the field it continues. After a SyntaxError, or once `end` has been called, every call throws.
+ */
+export class CsvStream {
+  private state = State.RowStart;
+  /** Whether the `\r` waited on in `CarriageReturn` came after a closing quote. */
+  private crAfterQuote = false;
+  private atInputStart = true;
+  /** Offset in the whole input of the start of the next chunk. */
+  private offset = 0;
+  private field = "";
+  private row: string[] = [];
+  private failure: Error | undefined;
+
+  /** Takes the next chunk and returns each row whose row end has now arrived. */
+  push(chunk: string): string[][] {
+    this.check();
+    try {
+      return this.feed(chunk);
+    } catch (e) {
+      this.failure = e as Error;
+      throw e;
+    }
+  }
+
+  /** Ends the input and returns the rows not returned yet. */
+  end(): string[][] {
+    this.check();
+    this.failure = new Error("the stream has already ended");
+    const rows: string[][] = [];
+    switch (this.state) {
+      case State.RowStart:
+        return rows;
+      case State.Quoted:
+        throw (this.failure = new SyntaxError("a quoted field is still open at the end of the input"));
+      case State.CarriageReturn:
+        if (this.crAfterQuote) throw (this.failure = this.afterQuoteError("\r", this.offset - 1));
+        this.field += "\r";
+        break;
+    }
+    this.endRow(rows);
+    return rows;
+  }
+
+  private check() {
+    if (this.failure) throw this.failure;
+  }
+
+  private afterQuoteError(c: string, at: number) {
+    return new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${at}`);
+  }
+
+  private endRow(rows: string[][]) {
+    this.row.push(this.field);
+    rows.push(this.row);
+    this.row = [];
+    this.field = "";
+    this.state = State.RowStart;
+  }
+
+  private feed(chunk: string): string[][] {
+    const rows: string[][] = [];
+    const n = chunk.length;
+    let i = 0;
+    if (this.atInputStart && n > 0) {
+      this.atInputStart = false;
+      if (chunk[0] === "﻿") i = 1;
+    }
+    while (i < n) {
+      const c = chunk[i]!;
+      switch (this.state) {
+        case State.RowStart:
+        case State.FieldStart:
+          if (c === '"') {
+            this.state = State.Quoted;
+            i++;
+          } else this.state = State.Unquoted;
+          break;
+        case State.Unquoted: {
+          let j = i;
+          while (j < n) {
+            const d = chunk[j];
+            if (d === "," || d === "\n" || d === "\r" || d === '"') break;
+            j++;
+          }
+          this.field += chunk.slice(i, j);
+          i = j;
+          if (i === n) break;
+          const d = chunk[i++];
+          if (d === '"') throw new SyntaxError(`a quote in a field that is not quoted, at offset ${this.offset + i - 1}`);
+          if (d === ",") {
+            this.row.push(this.field);
+            this.field = "";
+            this.state = State.FieldStart;
+          } else if (d === "\n") this.endRow(rows);
+          else {
+            this.state = State.CarriageReturn;
+            this.crAfterQuote = false;
+          }
+          break;
+        }
+        case State.Quoted: {
+          const j = chunk.indexOf('"', i);
+          if (j < 0) {
+            this.field += chunk.slice(i);
+            i = n;
+          } else {
+            this.field += chunk.slice(i, j);
+            i = j + 1;
+            this.state = State.QuoteInQuoted;
+          }
+          break;
+        }
+        case State.QuoteInQuoted:
+          if (c === '"') {
+            this.field += '"';
+            this.state = State.Quoted;
+            i++;
+          } else this.state = State.AfterQuote;
+          break;
+        case State.AfterQuote:
+          i++;
+          if (c === ",") {
+            this.row.push(this.field);
+            this.field = "";
+            this.state = State.FieldStart;
+          } else if (c === "\n") this.endRow(rows);
+          else if (c === "\r") {
+            this.state = State.CarriageReturn;
+            this.crAfterQuote = true;
+          } else throw this.afterQuoteError(c, this.offset + i - 1);
+          break;
+        case State.CarriageReturn:
+          if (c === "\n") {
+            i++;
+            this.endRow(rows);
+          } else if (this.crAfterQuote) {
+            throw this.afterQuoteError("\r", this.offset + i - 1);
+          } else {
+            // The `\r` is part of the field, and `c` is read again as the next character of it.
+            this.field += "\r";
+            this.state = State.Unquoted;
+          }
+          break;
+      }
+    }
+    this.offset += n;
+    return rows;
+  }
+}

